Notation mem := (word -> option byte).

Definition efs_entry : Z := 0x48d88.
Definition efs_retB : Z := 0x48e28.
Definition str_freearray : Z := 0x1a490.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition efs_frame (m : mem) (sp : word) (ra s0 s1 s2 s3 : word) : Prop :=
  exists junk, rw_cells asegs m (bv_unsigned sp - 48) [CB 8 junk; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Lemma efs_fast_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (R num nfree mfa auser muser lo : Z),
  ri_core m R nfree mfa auser muser ->
  (0 <= nfree < 2^64)%Z -> (0 <= mfa <= 2^29)%Z -> (0 <= auser < 2^64)%Z -> (0 <= muser < 2^64)%Z ->
  (0 <= num < 2^32)%Z -> (4 * num <= mfa)%Z ->
  (0 < R)%Z -> (R + 64 <= lo)%Z ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 48)%Z -> (bv_unsigned sp <= 2^47)%Z ->
  mem_inv asegs m ->
  evt asegs (frame_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc 1 [(bv_unsigned sp - 48, bv_unsigned sp)]%Z lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 INST) (Z_to_bv 64 R) a2 (Z_to_bv 64 num) a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 efs_entry) fc None m (seg_rom asegs)).
